import{z as A,x as d,o as s,c as i,q as l,j as c,D as o,d as E,s as n,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"套接字选项","description":"","frontmatter":{"title":"套接字选项","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-options.md","filePath":"cs/socket-options.md","lastUpdated":1791063341000}'),p={name:"cs/socket-options.md"};function B(P,e,T,S,C,_){const t=d("Mermaid");return s(),i("div",null,[e[2]||(e[2]=l('<h1 id="套接字选项" tabindex="-1">套接字选项 <a class="header-anchor" href="#套接字选项" aria-label="Permalink to &quot;套接字选项&quot;">​</a></h1><div class="epigraph"><p>setsockopt 把传输与缓冲旋钮暴露给应用：不延迟、保活、地址复用、时间戳，而不改系统调用号。</p><footer>—— 据 POSIX setsockopt；Stevens, <em>UNP</em>；Linux socket(7)、tcp(7)</footer></div><p><a href="/cs/rdma-os">上一课</a>留下的缺口接到本课。 <a href="/cs/kernel-tcp-impl">TCP 实现</a> 与 <a href="/cs/socket-buffers">缓冲</a> 已有内核对象。应用通过 <strong>套接字选项</strong> 触及它们，而不是重编内核。网络栈课序在此收口，下一单元回到内存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>默认 Nagle 合并小写；延迟 ACK 交互差。<code>TCP_NODELAY</code> 关 Nagle。<code>SO_REUSEADDR</code>/<code>SO_REUSEPORT</code> 管绑定。<code>SO_KEEPALIVE</code> 探活。<code>SO_TIMESTAMP</code> 把 RX 时间戳交用户。缺口：选项在 SOL_SOCKET vs IPPROTO_TCP 层；有的继承 listen，有的要在 connect 前设；与 <a href="/cs/napi">busy poll</a> 的 <code>SO_BUSY_POLL</code> 接头。本课不把每一选项写成 man 页拷贝。</p><p><span class="marginnote">术语翻译：Nagle 算法是把小包攒一攒再发，省协议头开销；延迟 ACK 是收到数据不立刻确认，等捎带或超时。两者叠加，交互式程序（比如 SSH 里打字）会莫名卡半拍——<code>TCP_NODELAY</code> 关掉前者，<code>TCP_QUICKACK</code> 关掉后者。</span></p><p><span class="marginnote">TCP_QUICKACK、CORK、MAXSEG 是同一层的细旋钮。错误的 REUSEPORT 负载均衡会打乱 CPU 亲和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>setsockopt(fd, level, opt, ...)</code> 改 <code>sock</code> 字段，后续 <code>tcp_sendmsg</code> 读这些字段。对照 <a href="/cs/file-locking">fcntl 文件锁</a>：一个管文件劝告锁，一个管传输行为。对照 sysctl：全局默认，选项是 per-fd 覆盖。对照 RDMA：verbs 不走这套。</p><p><span class="marginnote">直觉类比：<code>level</code> 参数像选菜单层级——SOL_SOCKET 是「所有传输通用」的基础菜单，IPPROTO_TCP 是 TCP 专属菜单。层选错了，内核要么报 ENOPROTOOPT，要么静默不生效；排查时先核对层，再核对选项名。</span></p>',10)),(s(),c(r,null,{default:o(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22setsockopt%22%5D%20--%3E%20SK%5B%22sock%20%E5%AD%97%E6%AE%B5%22%5D%0A%20%20SK%20--%3E%20TCP%5B%22%E5%8F%91%E9%80%81%2FACK%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SK%20--%3E%20UDP%5B%22UDP%20%E7%BC%93%E5%86%B2%E4%B8%8E%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"选项把内核 TCP/UDP 的工程折中变成可调 ABI，使 HTTP 服务器与 SSH 能不同。它们不创造新协议。不要写成云负载均衡产品文档。与 netfilter：选项改端行为，不替代防火墙。",-1)),e[5]||(e[5]=a("p",null,[E("安全：有的选项要特权（如绑定低端口是另一件事，"),a("code",null,"IP_TRANSPARENT"),E(" 要 cap）。")],-1)),e[6]||(e[6]=a("p",null,[E("实现上：SO_REUSEPORT 的哈希把同端口多监听器分流，和 RSS 一样怕连接不对称。TCP_USER_TIMEOUT 管未 ACK 数据的死亡，和 KEEPALIVE 探空闲不是一回事。 读法上只引用"),a("a",{href:"/cs/rdma-os"},"上一课"),E("的结论，不把对象换成训练推理或限价簿。")],-1)),(s(),c(r,null,{default:o(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%83%B3%E8%B0%83%E4%B8%80%E4%B8%AA%E8%A1%8C%E4%B8%BA%3A%20%E6%97%8B%E9%92%AE%E6%80%8E%E4%B9%88%E9%80%89%3F%22%5D%20--%3E%20L%7B%22%E4%BD%9C%E7%94%A8%E5%AF%B9%E8%B1%A1%E6%98%AF%E8%B0%81%3F%22%7D%0A%20%20L%20--%20%22%E9%80%9A%E7%94%A8%3A%20%E7%BC%93%E5%86%B2%2F%E5%A4%8D%E7%94%A8%2F%E4%BF%9D%E6%B4%BB%22%20--%3E%20S%5B%22SOL_SOCKET%20%E5%B1%82%22%5D%0A%20%20L%20--%20%22TCP%20%E8%A1%8C%E4%B8%BA%3A%20NODELAY%20%E7%AD%89%22%20--%3E%20T%5B%22IPPROTO_TCP%20%E5%B1%82%22%5D%0A%20%20L%20--%20%22%E5%85%A8%E4%BD%93%E6%96%B0%E8%BF%9E%E6%8E%A5%E7%9A%84%E9%BB%98%E8%AE%A4%22%20--%3E%20Y%5B%22sysctl%20%E6%94%B9%E5%85%A8%E5%B1%80%20per-fd%20%E5%86%8D%E8%A6%86%E7%9B%96%22%5D%0A%20%20S%20--%3E%20W%7B%22%E8%AE%BE%E7%BD%AE%E6%97%B6%E6%9C%BA%3F%22%7D%0A%20%20T%20--%3E%20W%0A%20%20W%20--%20%22TCP%20%E9%80%89%E9%A1%B9%E9%A1%BB%E5%9C%A8%20connect%20%E5%89%8D%22%20--%3E%20E%5B%22%E6%99%9A%E4%BA%86%E5%AF%B9%E6%96%B0%E8%BF%9E%E6%8E%A5%E4%B8%8D%E7%94%9F%E6%95%88%22%5D%0A%20%20W%20--%20%22%E9%83%A8%E5%88%86%E9%80%89%E9%A1%B9%E9%9A%8F%20accept%20%E7%BB%A7%E6%89%BF%22%20--%3E%20I%5B%22%E5%9C%A8%E7%9B%91%E5%90%AC%E5%A5%97%E6%8E%A5%E5%AD%97%E4%B8%8A%E8%AE%BE%E4%B8%80%E6%AC%A1%E5%8D%B3%E5%8F%AF%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p><span class="marginnote">这张图回答「一个调优需求该落在哪一层、什么时候设」：先按对象分层，再按时机分岔——TCP 专属选项通常要在 <code>connect</code> 之前设好，而监听套接字上的部分选项会被 <code>accept</code> 出来的连接继承，一次设置管全部工作连接。</span></p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>套接字选项</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MPTCP 的 sockopt 全集。不保证 Windows 同名选项语义——<a href="/cs/windows-nt-contrast">NT 对照</a> 后课。内存进阶第一课：页如何被反向找到，以便回收与 unmap。</p><p><span class="marginnote">常见误区：把 SO_KEEPALIVE 当成应用层心跳。它的默认探测间隔常以小时计（可经 TCP_KEEPIDLE 调短），且只证明「TCP 连接还在」，不证明对端应用还能干活；中间的 NAT、防火墙也可能照样拆连接。真正的健康检查要在应用层自己发。</span></p><p>版本字段会变，课序钉的是机制对象「套接字选项」，不是某一主线内核的结构体名。 后课默认：应用可用 sockopt 调缓冲与 TCP 行为。内核如何从物理页反查映射，下一课 rmap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>sockopt 是 per-socket 的内核旋钮。</li><li>分层在 SOL_SOCKET 与协议级。</li><li>反向映射 rmap 是下一单元。</li><li>出处：Stevens <em>UNP</em>；Linux <code>socket(7)</code>、<code>tcp(7)</code>；POSIX。</li></ul>',9))])}const O=A(p,[["render",B]]);export{D as __pageData,O as default};
